-- PRODUCTION ONLY: confirm SQL Editor URL contains rtgqyctqjfoercdymssd.
-- SQL session metadata alone cannot prove the Supabase Project ref.
-- Applies only usage_analytics and its own 00:10 JST maintenance job.
-- Requires existing Supabase Cron (pg_cron); missing/conflicting configuration rolls everything back.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
SET LOCAL TIME ZONE 'UTC';
DO $usage_apply$
DECLARE source_sql text := convert_from(decode('','base64'),'UTF8');
 applied boolean := false;
BEGIN
 IF current_user <> 'postgres' THEN RAISE EXCEPTION 'USAGE_UNEXPECTED_ROLE'; END IF;
 IF encode(sha256(convert_to(source_sql,'UTF8')),'hex') <> 'a145e6777a82828aed3abf8bbfc5d50fe4672fe0a254016e8466f16ac8beef96' THEN RAISE EXCEPTION 'USAGE_SOURCE_SHA256_MISMATCH'; END IF;
 LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261124000100') THEN
  IF NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261124000100'
    AND name='usage_analytics' AND statements=ARRAY[source_sql]) THEN RAISE EXCEPTION 'USAGE_HISTORY_MISMATCH'; END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='snownow_private'
    AND c.relname IN ('usage_days','usage_events','usage_daily_summary') AND c.relkind='r' AND c.relrowsecurity)<>3
    OR to_regprocedure('public.record_usage_events(jsonb)') IS NULL
    OR to_regprocedure('public.maintain_usage_analytics()') IS NULL
    OR to_regclass('snownow_private.usage_report') IS NULL THEN RAISE EXCEPTION 'USAGE_APPLIED_SCHEMA_MISMATCH'; END IF;
 ELSE
  IF to_regclass('snownow_private.usage_days') IS NOT NULL OR to_regclass('snownow_private.usage_events') IS NOT NULL
    OR to_regclass('snownow_private.usage_daily_summary') IS NOT NULL OR to_regclass('snownow_private.usage_report') IS NOT NULL
    OR to_regprocedure('public.record_usage_events(jsonb)') IS NOT NULL OR to_regprocedure('public.maintain_usage_analytics()') IS NOT NULL
    OR to_regprocedure('snownow_private.usage_rollup(date)') IS NOT NULL OR to_regprocedure('snownow_private.usage_digest(date)') IS NOT NULL
    THEN RAISE EXCEPTION 'USAGE_OBJECT_COLLISION'; END IF;
  EXECUTE source_sql;
  INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20261124000100','usage_analytics',ARRAY[source_sql]);
  applied:=true;
 END IF;
 PERFORM set_config('snowviking.usage_apply_result',jsonb_build_object('status',CASE WHEN applied THEN 'USAGE_ANALYTICS_APPLIED' ELSE 'USAGE_ANALYTICS_ALREADY_APPLIED' END,'version','20261124000100','source_sha256','a145e6777a82828aed3abf8bbfc5d50fe4672fe0a254016e8466f16ac8beef96')::text,true);
END;
$usage_apply$;
DO $setup$
DECLARE requested_command text := 'SET statement_timeout = ''30s''; SELECT public.maintain_usage_analytics();';
BEGIN
 IF to_regnamespace('cron') IS NULL THEN RAISE EXCEPTION 'USAGE_CRON_EXTENSION_NOT_AVAILABLE'; END IF;
 IF coalesce(current_setting('cron.timezone',true),'GMT') NOT IN ('UTC','GMT','Etc/UTC') THEN
  RAISE EXCEPTION 'USAGE_CRON_TIMEZONE_REQUIRES_REVIEW'; END IF;
 IF EXISTS(SELECT 1 FROM cron.job WHERE jobname='snowviking-usage-maintenance') THEN
  IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='snowviking-usage-maintenance'
    AND schedule='10 15 * * *' AND cron.job.command=requested_command AND active) THEN
   RAISE EXCEPTION 'USAGE_EXISTING_CRON_REQUIRES_REVIEW'; END IF;
 ELSE PERFORM cron.schedule('snowviking-usage-maintenance','10 15 * * *',requested_command); END IF;
END;
$setup$;
SELECT jobid,jobname,schedule,active FROM cron.job WHERE jobname='snowviking-usage-maintenance';

SELECT current_setting('snowviking.usage_apply_result')::jsonb || jsonb_build_object(
 'cron_00_10_jst',EXISTS(SELECT 1 FROM cron.job WHERE jobname='snowviking-usage-maintenance' AND schedule='10 15 * * *' AND active),
 'rls_tables',(SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='snownow_private' AND c.relname IN ('usage_days','usage_events','usage_daily_summary') AND c.relkind='r' AND c.relrowsecurity)
) AS result;
COMMIT;
